import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

// tails[k] = 長さ k+1 の増加部分列の末尾として考えられる最小値
const tails: number[] = [];
for (const x of a) {
  // x 以上の最初の位置を二分探索する
  let lo = 0;
  let hi = tails.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (tails[mid] < x) lo = mid + 1;
    else hi = mid;
  }
  tails[lo] = x; // lo === tails.length なら末尾に追加される
}
console.log(tails.length);
